27	
28	class ResumeDriver
29	{
30	public:
31	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
32	  // dmcontrol/dmstatus are run-control registers specific to this driver.
33	  static constexpr uint8_t kData0      = kDmiData0;
34	  static constexpr uint8_t kData1      = kDmiData1;
35	  static constexpr uint8_t kDmcontrol  = 0x10;
36	  static constexpr uint8_t kDmstatus   = 0x11;
37	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
38	  static constexpr uint8_t kCommand    = kDmiCommand;
39	
40	  static constexpr uint16_t kCsrDpc      = 0x7B1;
41	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
42	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
43	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
44	  static constexpr uint16_t kCsrFcsr     = 0x003;
45	  static constexpr uint16_t kCsrMstatus  = 0x300;
46	  static constexpr uint16_t kCsrMie      = 0x304;
47	  static constexpr uint16_t kCsrMtvec    = 0x305;
48	  static constexpr uint16_t kCsrMscratch = 0x340;
49	  static constexpr uint16_t kCsrMepc     = 0x341;
50	  static constexpr uint16_t kCsrMcause   = 0x342;
51	  static constexpr uint16_t kCsrMtval    = 0x343;
52	  static constexpr uint16_t kCsrMip      = 0x344;
53	  static constexpr uint16_t kCsrMcycle   = 0xB00;
54	  static constexpr uint16_t kCsrMinstret = 0xB02;
55	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
56	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
57	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
58	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
59	  static constexpr uint16_t kCsrVstart   = 0x008;
60	  static constexpr uint16_t kCsrVxsat    = 0x009;
61	  static constexpr uint16_t kCsrVxrm     = 0x00A;
62	  static constexpr uint16_t kCsrVcsr     = 0x00F;
63	  static constexpr uint16_t kCsrVtype    = 0xC21;
64	  static constexpr uint16_t kCsrVl       = 0xC20;
65	
66	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
67	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
68	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
69	
70	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
71	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
72	
73	  static constexpr uint32_t kAbstractcsBusy       = hybrid::kAbstractcsBusy;
74	  static constexpr uint32_t kAbstractcsCmderrMask = hybrid::kAbstractcsCmderrMask;
75	
76	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
77	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
78	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
79	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
80	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
81	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
82	
83	  static constexpr unsigned kPollIterations = kDmiPollIterations;
84	
85	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
86	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
87	  // "unset" sentinel; a non-V resume never reads it. The simulator passes the
88	  // real value from platform.main_memory.
89	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
90	                        AndesCaps caps = AndesCaps::all())
91	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
92	  {}
93	
94	  void resume(const hybrid_state_v1& state)
95	  {
96	    if (state.magic != HYBRID_STATE_MAGIC)
97	      throw std::runtime_error("ResumeDriver::resume: bad magic");
98	    if (state.version != HYBRID_STATE_VERSION)
99	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
100	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
101	    if (state.priv == 2 || state.priv > 3)
102	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
103	
104	    // dmactive must transition 0->1 in its own write before any other
105	    // DMCONTROL bit is honored (RISC-V Debug Spec).
106	    bus_.write(kDmcontrol, kDmcontrolDmactive);
107	    request_halt();
108	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
109	
110	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
111	    // accepted (FS or VS == Off disables the extension and the hart NACKs
112	    // the writes). The drained state.mstatus may legitimately carry FS or
113	    // VS at Off (e.g. an OS context-switched the regs away before the
114	    // trigger fired) -- gating the write on the drained field skips the
115	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
116	    // write mstatus when either extension is in scope; force-OR Initial
117	    // when the drained field is Off. This enable is local to the vsim
118	    // phase; the state.mstatus written to the handoff file is left
119	    // unmodified.
120	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
121	      uint64_t enable_mstatus = state.mstatus;
122	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
123	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
124	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
125	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
126	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
127	    }
128	
129	    // FPR restore (requires mstatus.FS enabled above): one abstract register
130	    // write per f-reg. Abstract-only by design, like every non-V register
131	    // block -- the Program Buffer is reserved for state the abstract command
132	    // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
133	    if (state.flags & HYBRID_FLAG_FP) {
134	      for (uint16_t i = 0; i < 32; ++i)
135	        write_64bit_register(regno_fpr(i), state.fpr[i]);
136	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
137	      // fallback scratch x5 is overwritten by the GPR loop below.
138	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
139	    }
140	
141	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
142	    // the GPR loop overwrites x5 afterward so state is preserved).
143	    if (state.flags & HYBRID_FLAG_V) {
144	      // V data regfile: reload v0..v31 from the shared scratch region via the
145	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
146	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
147	      // the restore then overwrites with the architectural values. The sweep
148	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
149	      // below restores all three. The scratch is vlenb-packed
150	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
151	      if (scratch_gpa_ == kVScratchGpaUnset)
152	        throw std::runtime_error(
153	          "ResumeDriver::resume: V state present but scratch GPA unset");
154	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
155	
156	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
157	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
158	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
159	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
160	      write_64bit_register(regno_gpr(5), state.vl);
161	      write_64bit_register(regno_gpr(6), state.vtype);
162	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
163	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
164	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
165	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
166	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
167	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
168	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
169	    }
170	
171	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
172	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
173	    // in the drained privilege; M-mode states skip the write (prv already 3).
174	    // Before the GPR loop: a PB fallback would clobber scratch x5.
175	    if (state.priv != 3) {
176	      // L2 slice: with PMP implemented and no matching entry, every S/U
177	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
178	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
179	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
180	      // RV64. Tolerant writes: entries beyond what the hart implements
181	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
182	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
183	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
184	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
185	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
186	
187	      const uint64_t dcsr =
188	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
189	      write_csr_abstract_or_pb(kCsrDcsr,
190	                               (dcsr & ~uint64_t{0x3}) | state.priv);
191	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
192	      // silently measure the ROI in the wrong privilege. Verify and abort.
193	      const uint64_t got =
194	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
195	        & 0x3u;
196	      if (got != state.priv)
197	        throw std::runtime_error(
198	          "ResumeDriver::resume: engine does not implement privilege level "
199	          + std::to_string(state.priv)
200	          + " (dcsr.prv pinned to " + std::to_string(got)
201	          + "); pick an S/U-capable engine");
202	    }
203	
204	    // Andes V5 + M-ext CSR restore (abstract-only). See restore_andes_m_ext.
205	    restore_andes_m_ext(state);
206	
207	    // GPRs x1..x31 + DPC (after the V CSRs so the PB scratch GPRs the V block
208	    // staged -- x5/x6/x7 -- are safe to overwrite): one abstract register
209	    // write each (DATA0/DATA1 + Access-Register COMMAND), abstract-only by
210	    // design. x0 is hardwired zero and is skipped.
211	    for (uint16_t i = 1; i < 32; ++i)
212	      write_64bit_register(regno_gpr(i), state.gpr[i]);
213	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
214	
215	    write_csr_tolerant(kCsrMtvec, state.mtvec);
216	
217	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
218	    // register with no hardware side effects, legal to use inside a trap-free
219	    // ROI. Restore it so a value stashed before the handoff survives into the
220	    // vsim phase.
221	    write_csr_tolerant(kCsrMscratch, state.mscratch);
222	
223	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
224	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
225	    // value stashed before the handoff must survive into the vsim phase (same
226	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
227	    // hardware-driven pending bits, or mtval on a core that hardwires it)
228	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
229	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
230	    write_csr_tolerant(kCsrMepc,   state.mepc);
231	    write_csr_tolerant(kCsrMcause, state.mcause);
232	    write_csr_tolerant(kCsrMtval,  state.mtval);
233	    write_csr_tolerant(kCsrMie,    state.mie);
234	    write_csr_tolerant(kCsrMip,    state.mip);
235	
236	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
237	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
238	    // caches) but has no cache model, so without this the cycle engine resumes
239	    // at the ROI with caches at their reset default -- DISABLED -- and the
240	    // whole measured window runs uncached, inflating it severalfold. Tolerant
241	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
242	    // write as a no-op, and a drained 0 (caches were off) restores the reset
243	    // state, so this is always safe to issue.
244	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
245	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
246	
247	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
248	    // from QEMU1's drain value. Without this, vsim's local counter starts
249	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
250	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
251	    // overwrite here as the GPR loop already ran.
252	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
253	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
254	
255	    clear_cmderr_if_set();
256	    request_resume();
257	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
258	                   "ResumeDriver resume");
259	  }
