261	private:
262	  void request_halt()
263	  {
264	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
265	  }
266	
267	  void request_resume()
268	  {
269	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
270	  }
271	
272	  void write_64bit_register(uint16_t regno, uint64_t value)
273	  {
274	    write_register_abstract(bus_, regno, value);
275	  }
276	
277	  // Andes V5 + M-ext CSR restore: one tolerant abstract write per CSR -- the 13
278	  // Andes scalars via the HYBRID_ANDES_CSR_LIST X-macro, then PMA (pmaaddr0..15
279	  // before the even pmacfg, mirroring the PMP restore ordering). Abstract-only
280	  // by design: a batched Program-Buffer sweep can't tolerate a cmderr on one
281	  // CSR without corrupting the rest of the batch (a WARL/read-only CSR faults
282	  // the whole group), whereas the per-CSR abstract path clears the error and
283	  // moves on. Caps-gated: a CSR the target core lacks (caps_.supports_csr
284	  // false) is skipped, so an abstract write to an unimplemented CSR can't hang
285	  // the DM handshake (the ucode/mecc_code cases). The baseline and write-mask
286	  // gating wrap these writes at their later commits.
287	  void restore_andes_m_ext(const hybrid_state_v1& state)
288	  {
289	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
290	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
291	    if (!andes && !mext) return;
292	
293	    if (andes) {
294	#define X(field, addr, name) \
295	    if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
296	      HYBRID_ANDES_CSR_LIST(X)
297	#undef X
298	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
299	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
300	          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
301	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
302	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
303	          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
304	    }
305	    if (mext) {
306	#define X(field, addr, name) \
307	    if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.m_ext.field);
308	      HYBRID_M_EXT_CSR_LIST(X)
309	#undef X
310	    }
311	  }
312	
313	  // Abstract-first CSR write with Program Buffer fallback.
314	  // Tries an abstract register write; if the DM signals cmderr, clears it,
315	  // stages the value in scratch_gpr via abstract GPR write, then executes a
316	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
317	  // to x5 (t0) which the GPR restore loop overwrites later.
318	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
319	                                 uint8_t scratch_gpr = 5)
320	  {
321	    write_64bit_register(regno_csr(csr), value);
322	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
323	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
324	    write_64bit_register(regno_gpr(scratch_gpr), value);
325	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
326	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
327	  }
328	
329	  // Write a CSR-addressable register and clear any cmderr the DM raised.
330	  // Used for CSRs whose abstract-access support may be implementation
331	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
332	  // remaining writes.
333	  void write_csr_tolerant(uint16_t csr, uint64_t value)
334	  {
335	    write_64bit_register(regno_csr(csr), value);
336	    clear_cmderr_if_set();
337	  }
338	
339	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
340	  // is rejected until the bits are W1C-cleared. We tolerate per-register
341	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
342	  // error before resuming so the hart isn't left in a stuck state.
343	  // B17: record the last observed non-zero cmderr and a clear count so a
344	  // partially-broken restore is observable via the public accessors
345	  // instead of silently swallowed.
346	  void clear_cmderr_if_set()
347	  {
348	    const auto status = bus_.read(kAbstractcs);
349	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
350	    if (code != 0u) {
351	      last_observed_cmderr_ = code;
352	      ++cmderr_clear_count_;
353	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
354	    }
355	  }
356	
357	  DmiBus& bus_;
358	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
359	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
360	  uint32_t last_observed_cmderr_ = 0;
361	  uint64_t cmderr_clear_count_   = 0;
362	
363	public:
364	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
365	  // at least one abstract write tripped a sticky cmderr the restore
366	  // tolerated by clearing. cmderr_clear_count() is the total number of
367	  // such clears across all calls into clear_cmderr_if_set() this run.
368	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
369	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
370	};
