372	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
373	// via an Abstract Command. Halts-and-reads contract: caller must have the
374	// hart in the halted state. Shared with StateDrain (drain at exit). If
375	// abstractcs.cmderr goes sticky after the command, the helper clears it and
376	// reports nullopt rather than blocking the caller -- a missing CSR mirrors as
377	// absent instead of corrupting the adjacent field.
378	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
379	                                     const char* poll_label
380	                                       = "read_register_64")
381	  -> std::optional<uint64_t>
382	{
383	  using RD = ResumeDriver;
384	  bus.write(RD::kCommand,
385	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
386	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
387	  const auto status = bus.read(RD::kAbstractcs);
388	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
389	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
390	    return std::nullopt;
391	  }
392	  const uint64_t lo = bus.read(RD::kData0);
393	  const uint64_t hi = bus.read(RD::kData1);
394	  return lo | (hi << 32);
395	}
396	
397	inline auto read_register_64(DmiBus& bus, uint16_t regno,
398	                             const char* poll_label = "read_register_64")
399	  -> uint64_t
400	{
401	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
402	}
