1266	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
1267	          "before the architectural V-CSR restore and counter restore")
1268	{
1269	  RecordingBus bus;
1270	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1271	
1272	  auto s = rv64_state(0x80001000, 0);
1273	  s.flags  |= HYBRID_FLAG_V;
1274	  s.vlenb  = 64;
1275	  s.vl     = 16;
1276	  s.vtype  = 0xC1;   // differs from the sweep's e8/m8 vtype (0xC3)
1277	  s.vstart = 7;
1278	
1279	  // L26: the scratch GPA is the runtime top-of-mmap value (kScratch), passed
1280	  // to the driver -- no longer a fixed constant. Assert the sweep stages it.
1281	  hybrid::ResumeDriver driver(bus, kScratch);
1282	  driver.resume(s);
1283	
1284	  // (a) all 32 registers are reloaded as 4 LMUL=8 groups: one vle8.v per group
1285	  //     base (v0/v8/v16/v24) covers 8 registers. The 4 loads land in any slot
1286	  //     of the single grouped Program-Buffer execution.
1287	  auto in_progbuf = [](const DmiOp& op, uint32_t insn) {
1288	    return op.kind == DmiOp::Kind::Write
1289	           && op.reg >= hybrid::kProgbuf0
1290	           && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
1291	           && op.value == insn;
1292	  };
1293	  std::vector<int> missing;
1294	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
1295	  for (uint16_t g = 0; g < 32; g += 8) {
1296	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(g), 7);
1297	    std::optional<std::size_t> at;
1298	    for (std::size_t i = 0; i < bus.ops.size(); ++i)
1299	      if (in_progbuf(bus.ops[i], want)) { at = i; break; }
1300	    if (!at) { missing.push_back(g); continue; }
1301	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
1302	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
1303	  }
1304	  CHECK(missing.empty());
1305	  REQUIRE(first_vle_idx.has_value());
1306	  REQUIRE(last_vle_idx.has_value());
1307	
1308	  // (b) batched sweep: the base pointer x7 is staged via a SINGLE abstract
1309	  //     write (the scratch base); the in-buffer addi advances it per register,
1310	  //     so there is no per-register x7 abstract write.
1311	  auto x7_gpa_staged = [&](uint64_t gpa) {
1312	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
1313	      const auto& op = bus.ops[i];
1314	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
1315	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
1316	          && ((op.value >> 16) & 1u)) {
1317	        const auto& d0 = bus.ops[i - 2];
1318	        const auto& d1 = bus.ops[i - 1];
1319	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
1320	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
1321	          return true;
1322	      }
1323	    }
1324	    return false;
1325	  };
1326	  // The base is staged once; the per-register scratch GPAs the OLD sweep poked
1327	  // into x7 are gone -- the in-buffer addi advances x7 one LMUL=8 group
1328	  // (8*vlenb bytes) at a time. (A second x7 write does occur, but from the
1329	  // later architectural GPR restore, not from the sweep.)
1330	  CHECK(x7_gpa_staged(kScratch));
1331	  CHECK(!x7_gpa_staged(kScratch + 1ull * HYBRID_VLEN_BYTES_MAX));
1332	  CHECK(!x7_gpa_staged(kScratch + 31ull * HYBRID_VLEN_BYTES_MAX));
1333	  bool addi_in_pb = false;
1334	  for (const auto& op : bus.ops)
1335	    if (in_progbuf(op, hybrid::encode_addi(7, 7, 8 * static_cast<int32_t>(s.vlenb))))
1336	      { addi_in_pb = true; break; }
1337	  CHECK(addi_in_pb);
1338	
1339	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
1340	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
1341	  //     (so the vle8.v insns cannot pollute the resumed counters).
1342	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
1343	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
1344	    const auto& op = bus.ops[i];
1345	    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
1346	    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
1347	    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
1348	    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
1349	  }
1350	  REQUIRE(vstart_cmd_idx.has_value());
1351	  REQUIRE(mcycle_cmd_idx.has_value());
1352	  CHECK(*last_vle_idx < *vstart_cmd_idx);
1353	  CHECK(*last_vle_idx < *mcycle_cmd_idx);
1354	}
