// LG1 (liveness gate): supply the engine's own reset-state drain. A tolerant
// CSR write whose drained value equals this baseline is skipped -- the write
// would be a no-op, and every DM operation costs hundreds of simulated
// cycles. Unset (default) keeps transport-everything. Always-live state
// (mstatus, GPRs, dpc, dcsr, mcycle, minstret, the S/U PMP mirror) is never
// gated.
void set_reset_baseline(const hybrid_state_v1& b)
{
  baseline_ = b;
  has_baseline_ = true;
}

// Number of tolerant CSR writes elided by the reset baseline this resume.
auto baseline_skip_count() const -> uint64_t { return baseline_skip_count_; }

void resume(const hybrid_state_v1& state)

// Andes V5 + M-ext CSR restore (abstract-only, LG1-gated). See
// restore_andes_m_ext.
restore_andes_m_ext(state);

